t.script:
document.addEventListener("DOMContentLoaded", function() {
    var dateLabels = ;
    var dateLabelsRaw = ;
    var todayStr = ;

    function parseLocalDate(dateStr) {
        var parts = (dateStr || '').split('-').map(Number);
        if (parts.length !== 3) return null;
        return new Date(parts[0], parts[1] - 1, parts[2]).getTime();
    }

    function formatFullDateLabel(rawDate) {
        var parts = (rawDate || '').split('-').map(Number);
        if (parts.length !== 3) return rawDate || '';
        return new Intl.DateTimeFormat('es-MX', {
            day: 'numeric',
            month: 'long',
            year: 'numeric'
        }).format(new Date(parts[0], parts[1] - 1, parts[2]));
    }

    function tooltipFullDateTitle(items) {
        if (!items.length) return '';
        return formatFullDateLabel(dateLabelsRaw[items[0].dataIndex]);
    }

    function tooltipFullDateTitleFrom(rawLabels) {
        return function(items) {
            if (!items.length) return '';
            return formatFullDateLabel(rawLabels[items[0].dataIndex]);
        };
    }

    // Helper to get X position for "Today" line
    function getXForToday(chart, dateLabelsRaw, todayStr) {
        if (!dateLabelsRaw || !todayStr || dateLabelsRaw.length === 0) return null;
        var todayTime = parseLocalDate(todayStr);
        var points = dateLabelsRaw.map(function(value, index) {
            return {
                index: index,
                time: parseLocalDate(value)
            };
        }).filter(function(point) {
            return point.time !== null;
        });
        if (!points.length || todayTime === null) return null;

        var minTime = points[0].time;
        var maxTime = points[points.length - 1].time;

        if (minTime > todayTime) return null;
        if (todayTime > maxTime) return null;

        function getXForIndex(index) {
            if (chart.scales.x.getPixelForValue) {
                return chart.scales.x.getPixelForValue(index);
            }
            return chart.scales.x.getPixelForTick(index);
        }

        if (points.length === 1) {
            if (points[0].time === todayTime) {
                return getXForIndex(points[0].index);
            }
        }

        for (var i = 0; points.length - 1 > i; i++) {
            if (todayTime >= points[i].time) {
                if (points[i+1].time >= todayTime) {
                    var t0 = points[i].time;
                    var t1 = points[i+1].time;
                    var ratio = t1 === t0 ? 0 : (todayTime - t0) / (t1 - t0);

                    var x0 = getXForIndex(points[i].index);
                    var x1 = getXForIndex(points[i+1].index);

                    return x0 + ratio * (x1 - x0);
                }
            }
        }
        return null;
    }

    function getTodayIndex(dateLabelsRaw, todayStr) {
        var todayTime = parseLocalDate(todayStr);
        if (!dateLabelsRaw || todayTime === null) return -1;
        for (var i = 0; dateLabelsRaw.length > i; i++) {
            if (parseLocalDate(dateLabelsRaw[i]) === todayTime) {
                return i;
            }
        }
        return -1;
    }

    var todayIndex = getTodayIndex(dateLabelsRaw, todayStr);

    function isChartCutPoint(dataIndex) {
        if (dataIndex === todayIndex) return true;
        if (dataIndex === dateLabels.length - 1) return true;
        return false;
    }

    function pointRadiusForCut(context) {
        return context.dataIndex === todayIndex ? 5 : 2;
    }

    function pointHoverRadiusForCut(context) {
        return context.dataIndex === todayIndex ? 7 : 5;
    }

    function formatCurrencyShort(value) {
        return new Intl.NumberFormat('es-MX', {
            style: 'currency',
            currency: 'MXN',
            notation: 'compact',
            maximumFractionDigits: 1
        }).format(value);
    }

    function hideChartLoader(chart) {
        var canvas = chart.canvas;
        var frame = canvas ? canvas.closest('.portal-project-chart-frame') : null;
        var loader = frame ? frame.querySelector('.portal-project-chart-loader') : null;
        if (frame) {
            frame.classList.add('is-loaded');
        }
        if (loader) {
            loader.classList.add('is-loaded');
        }
    }

    const chartLoaderPlugin = {
        id: 'chartLoader',
        afterRender: hideChartLoader,
        afterDraw: hideChartLoader
    };

    // Today vertical cut line plugin
    const todayLinePlugin = {
        id: 'todayLine',
        afterDatasetsDraw: function(chart, args, options) {
            try {
                options = options || {};
                var dateLabelsRaw = options.dateLabelsRaw;
                var todayStr = options.todayStr;
                if (!chart.chartArea || !chart.scales || !chart.scales.x) return;
                var xPos = getXForToday(chart, dateLabelsRaw, todayStr);
                if (xPos !== null) {
                    var ctx = chart.ctx;
                    var area = chart.chartArea;
                    var label = options.label || 'HOY';
                    var lineColor = options.color || '#111827';
                    var showLabel = options.showLabel !== false;
                    ctx.save();
                    ctx.beginPath();
                    ctx.strokeStyle = lineColor;
                    ctx.lineWidth = 2;
                    ctx.setLineDash([5, 4]);
                    ctx.moveTo(xPos, area.top);
                    ctx.lineTo(xPos, area.bottom);
                    ctx.stroke();

                    if (!showLabel) {
                        ctx.restore();
                        return;
                    }

                    ctx.setLineDash([]);
                    ctx.font = 'bold 10px sans-serif';
                    ctx.textAlign = 'center';
                    ctx.textBaseline = 'middle';
                    var metrics = ctx.measureText(label);
                    var paddingX = 5;
                    var labelWidth = metrics.width + paddingX * 2;
                    var labelHeight = 18;
                    var labelX = Math.min(Math.max(xPos, area.left + labelWidth / 2), area.right - labelWidth / 2);
                    var labelY = area.top + 10;
                    ctx.fillStyle = '#ffffff';
                    ctx.strokeStyle = lineColor;
                    ctx.lineWidth = 1;
                    ctx.beginPath();
                    if (ctx.roundRect) {
                        ctx.roundRect(labelX - labelWidth / 2, labelY - labelHeight / 2, labelWidth, labelHeight, 4);
                    } else {
                        ctx.rect(labelX - labelWidth / 2, labelY - labelHeight / 2, labelWidth, labelHeight);
                    }
                    ctx.fill();
                    ctx.stroke();
                    ctx.fillStyle = lineColor;
                    ctx.fillText(label, labelX, labelY + 1);
                    ctx.restore();
                }
            } catch (error) {
                console.warn('No se pudo dibujar la linea de HOY en el grafico.', error);
            }
        }
    };

    var avanceReal = ;
    var avancePlaneado = ;

    var statesLabels = ;
    var statesData = ;

    var disciplineLabels = ;
    var disciplineData = ;

    var hhDateLabels = ;
    var hhDateLabelsRaw = ;
    var hhPlaneadas = ;
    var hhReales = ;

    var costoReal = ;
    var costoPlaneado = ;
    var costoComprometido = ;

    // Chart 1: Avance por Estado
    new Chart(document.getElementById('chartWorkOrdersState'), {
        type: 'bar',
        plugins: [ChartDataLabels, chartLoaderPlugin],
        data: {
            labels: statesLabels,
            datasets: [{
                label: 'Cantidad de OT',
                data: statesData,
                backgroundColor: ['#6c757d', '#007bff', '#ffc107', '#6f42c1', '#28a745'],
                borderRadius: 6
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
                legend: { display: false },
                datalabels: {
                    anchor: 'end',
                    align: 'top',
                    color: '#495057',
                    font: {
                        weight: 'bold',
                        size: 11
                    },
                    formatter: function(value) {
                        return value !== 0 ? value : '';
                    }
                }
            },
            scales: { y: { beginAtZero: true, grace: '15%', ticks: { precision: 0 } } }
        }
    });

    // Helper function for line-and-dot custom legend
    function generateLineLegend(chart, legendContainerId) {
        const legendContainer = document.getElementById(legendContainerId);
        if (legendContainer) {
            legendContainer.innerHTML = '';
            chart.data.datasets.forEach((dataset, i) => {
                const label = dataset.label;
                const color = dataset.borderColor || dataset.backgroundColor;
                const isBarLegend = legendContainerId === 'legendManHours';
                const markerHtml = isBarLegend
                    ? ``
                    : `


                    `;

                const legendItem = document.createElement('div');
                legendItem.className = 'legend-item d-flex align-items-center';
                legendItem.style.cursor = 'pointer';
                legendItem.style.fontSize = '0.85rem';
                legendItem.style.userSelect = 'none';
                legendItem.style.transition = 'opacity 0.2s';

                legendItem.innerHTML = `
                    ${markerHtml}
                    ${label}
                `;

                legendItem.addEventListener('click', () => {
                    const isVisible = chart.isDatasetVisible(i);
                    if (isVisible) {
                        chart.hide(i);
                        legendItem.style.opacity = '0.3';
                        legendItem.style.textDecoration = 'line-through';
                    } else {
                        chart.show(i);
                        legendItem.style.opacity = '1';
                        legendItem.style.textDecoration = 'none';
                    }
                });

                legendContainer.appendChild(legendItem);
            });
        }
    }

    // Chart 2: Evolución de Avance General
    const chartAdvance = new Chart(document.getElementById('chartGeneralAdvance'), {
        type: 'line',
        plugins: [ChartDataLabels, todayLinePlugin, chartLoaderPlugin],
        data: {
            labels: dateLabels,
            datasets: [
                {
                    label: 'Avance Real',
                    data: avanceReal,
                    borderColor: '#1b8b50',
                    backgroundColor: '#1b8b50',
                    tension: 0.2,
                    fill: false,
                    pointStyle: 'circle',
                    pointRadius: pointRadiusForCut,
                    pointHoverRadius: pointHoverRadiusForCut,
                    pointBorderColor: '#ffffff',
                    pointBorderWidth: 2
                },
                {
                    label: 'Avance Planeado',
                    data: avancePlaneado,
                    borderColor: '#ef8318',
                    backgroundColor: '#ef8318',
                    tension: 0.2,
                    fill: false,
                    pointStyle: 'circle',
                    pointRadius: pointRadiusForCut,
                    pointHoverRadius: pointHoverRadiusForCut,
                    pointBorderColor: '#ffffff',
                    pointBorderWidth: 2
                }
            ]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            layout: {
                padding: {
                    top: 12,
                    bottom: 12
                }
            },
            plugins: {
                datalabels: {
                    display: false,
                    align: function(context) {
                        if (context.datasetIndex === 0) {
                            return context.dataIndex % 2 === 0 ? 'top' : 'right';
                        }
                        return context.dataIndex % 2 === 0 ? 'bottom' : 'left';
                    },
                    anchor: 'end',
                    offset: function(context) {
                        return context.dataIndex % 2 === 0 ? 8 : 16;
                    },
                    clamp: true,
                    color: '#20242b',
                    backgroundColor: 'rgba(255, 255, 255, 0.88)',
                    borderColor: 'rgba(32, 36, 43, 0.15)',
                    borderWidth: 1,
                    borderRadius: 4,
                    padding: 3,
                    font: {
                        size: 9,
                        weight: 'bold'
                    },
                    formatter: function(value) {
                        return value.toFixed(1) + '%';
                    }
                },
                legend: { display: false },
                todayLine: {
                    dateLabelsRaw: dateLabelsRaw,
                    todayStr: todayStr,
                    label: 'REVISION',
                    color: '#813f32',
                    showLabel: false
                },
                tooltip: {
                    callbacks: {
                        title: tooltipFullDateTitle,
                        label: function(context) {
                            var label = context.dataset.label || '';
                            var value = context.parsed.y || 0;
                            return label + ': ' + value.toFixed(1) + '%';
                        },
                        footer: function(items) {
                            if (!items.length) return '';
                            var i = items[0].dataIndex;
                            var real = avanceReal[i] || 0;
                            var plan = avancePlaneado[i] || 0;
                            var gap = real - plan;
                            var sign = gap > 0 ? '+' : '';
                            return 'Desviacion vs plan: ' + sign + gap.toFixed(1) + '%';
                        }
                    }
                }
            },
            scales: {
                y: {
                    min: 0,
                    max: 100,
                    ticks: {
                        stepSize: 25,
                        callback: function(value) {
                            return value + '%';
                        }
                    }
                }
            }
        }
    });
    generateLineLegend(chartAdvance, 'legendGeneralAdvance');

    // Chart 3: Distribución por Disciplina
    const chartDiscipline = new Chart(document.getElementById('chartDisciplineDistribution'), {
        type: 'doughnut',
        plugins: [chartLoaderPlugin],
        data: {
            labels: disciplineLabels,
            datasets: [{
                data: disciplineData,
                backgroundColor: ['#2b66e3', '#2fa86c', '#f59e0b', '#d93838', '#8a5cd1', '#cbd5e1', '#e85858', '#49ccf9', '#f25fd0', '#b68ef2'],
                borderWidth: 2,
                borderColor: '#ffffff'
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            cutout: '70%',
            plugins: {
                legend: { display: false },
                tooltip: {
                    callbacks: {
                        label: function(context) {
                            const label = context.label || '';
                            const value = context.parsed || 0;
                            const dataset = context.chart.data.datasets[0];
                            let total = 0;
                            dataset.data.forEach(function(val, idx) {
                                if (isDoughnutItemVisible(context.chart, idx)) {
                                    total += val;
                                }
                            });
                            let percentage = '0%';
                            if (total !== 0) {
                                percentage = ((value / total) * 100).toFixed(1) + '%';
                            }
                            return ' ' + label + ': ' + value + ' (' + percentage + ')';
                        }
                    }
                }
            }
        }
    });

    const disciplineVisibility = disciplineData.map(() => true);

    function isDoughnutItemVisible(chart, index) {
        if (disciplineVisibility[index] !== undefined) {
            return disciplineVisibility[index];
        }
        const meta = chart.getDatasetMeta(0);
        const element = meta ? (meta.data ? meta.data[index] : null) : null;
        return !element || !element.hidden;
    }

    function setDoughnutItemVisibility(chart, index, visible) {
        disciplineVisibility[index] = visible;
        if (typeof chart.setDataVisibility === 'function') {
            chart.setDataVisibility(index, visible);
            return;
        }
        const meta = chart.getDatasetMeta(0);
        const element = meta ? (meta.data ? meta.data[index] : null) : null;
        if (element) {
            element.hidden = !visible;
        }
    }

    // Generate Custom Legend
    const legendContainer = document.getElementById('disciplineCustomLegend');
    if (legendContainer) {
        if (disciplineLabels.length) {
            legendContainer.innerHTML = '';
            const legendItems = [];
            disciplineLabels.forEach((label, i) => {
                const value = disciplineData[i];
                const color = chartDiscipline.data.datasets[0].backgroundColor[i % chartDiscipline.data.datasets[0].backgroundColor.length];

                const legendItem = document.createElement('div');
                legendItem.className = 'legend-item d-flex align-items-center justify-content-between mb-2';
                legendItem.style.cursor = 'pointer';
                legendItem.style.fontSize = '0.85rem';
                legendItem.style.userSelect = 'none';
                legendItem.style.transition = 'opacity 0.2s';
                legendItem.title = 'Clic para ocultar';

                legendItem.innerHTML = `



                        ${label}

                    ${value}
                `;

                legendItem.addEventListener('click', () => {
                    const isVisible = isDoughnutItemVisible(chartDiscipline, i);
                    setDoughnutItemVisibility(chartDiscipline, i, !isVisible);
                    chartDiscipline.update();

                    // Update legend item styling
                    if (isVisible) {
                        legendItem.style.opacity = '0.3';
                        legendItem.style.textDecoration = 'line-through';
                        legendItem.title = 'Clic para mostrar';
                    } else {
                        legendItem.style.opacity = '1';
                        legendItem.style.textDecoration = 'none';
                        legendItem.title = 'Clic para ocultar';
                    }

                    // Recalculate total for active items
                    let newTotal = 0;
                    chartDiscipline.data.datasets[0].data.forEach((val, idx) => {
                        if (isDoughnutItemVisible(chartDiscipline, idx)) {
                            newTotal += val;
                        }
                    });
                    document.getElementById('disciplineTotalValue').innerText = newTotal;
                });

                legendItems[i] = legendItem;
                legendContainer.appendChild(legendItem);
            });
        }
    }

    // Chart 4: HH Reales vs Planeadas
    const chartManHours = new Chart(document.getElementById('chartManHours'), {
        type: 'bar',
        plugins: [ChartDataLabels, chartLoaderPlugin],
        data: {
            labels: hhDateLabels,
            datasets: [
                {
                    label: 'HH Planeadas',
                    data: hhPlaneadas,
                    backgroundColor: '#007bff',
                    borderRadius: 4
                },
                {
                    label: 'HH Reales',
                    data: hhReales,
                    backgroundColor: '#28a745',
                    borderRadius: 4
                }
            ]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
                legend: { display: false },
                datalabels: {
                    anchor: 'end',
                    align: 'top',
                    color: '#495057',
                    font: {
                        weight: 'bold',
                        size: 11
                    },
                    formatter: function(value) {
                        return value !== 0 ? value : '';
                    }
                },
                tooltip: {
                    callbacks: {
                        title: tooltipFullDateTitleFrom(hhDateLabelsRaw)
                    }
                }
            },
            scales: { y: { beginAtZero: true, grace: '20%' } }
        }
    });
    generateLineLegend(chartManHours, 'legendManHours');

    // Chart 5: Costo antes de Fee, comprometido vs planeado (Acumulado)
    const chartCosts = new Chart(document.getElementById('chartAccumulatedCosts'), {
        type: 'line',
        plugins: [ChartDataLabels, todayLinePlugin, chartLoaderPlugin],
        data: {
            labels: dateLabels,
            datasets: [
                {
                    label: 'Costo antes de Fee',
                    data: costoReal,
                    borderColor: '#28a745',
                    backgroundColor: 'rgba(40, 167, 69, 0.1)',
                    fill: true,
                    tension: 0.2,
                    pointStyle: 'circle',
                    pointRadius: pointRadiusForCut,
                    pointHoverRadius: pointHoverRadiusForCut,
                    pointBorderColor: '#ffffff',
                    pointBorderWidth: 2
                },
                {
                    label: 'Valor Comprometido',
                    data: costoComprometido,
                    borderColor: '#6f42c1',
                    backgroundColor: 'rgba(111, 66, 193, 0.08)',
                    fill: false,
                    tension: 0.2,
                    pointStyle: 'circle',
                    pointRadius: pointRadiusForCut,
                    pointHoverRadius: pointHoverRadiusForCut,
                    pointBorderColor: '#ffffff',
                    pointBorderWidth: 2
                },
                {
                    label: 'Valor Planeado',
                    data: costoPlaneado,
                    borderColor: '#fd7e14',
                    backgroundColor: 'rgba(253, 126, 20, 0.1)',
                    fill: true,
                    tension: 0.2,
                    pointStyle: 'circle',
                    pointRadius: pointRadiusForCut,
                    pointHoverRadius: pointHoverRadiusForCut,
                    pointBorderColor: '#ffffff',
                    pointBorderWidth: 2
                }
            ]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            layout: {
                padding: {
                    top: 12,
                    bottom: 12
                }
            },
            scales: {
                y: {
                    beginAtZero: true,
                    grace: '18%',
                    ticks: {
                        callback: function(value) {
                            return new Intl.NumberFormat('es-MX', {
                                style: 'currency',
                                currency: 'MXN',
                                maximumFractionDigits: 0
                            }).format(value);
                        }
                    }
                }
            },
            plugins: {
                datalabels: {
                    display: false,
                    align: function(context) {
                        var isEvenPoint = context.dataIndex % 2 === 0;
                        if (context.dataset.label === 'Costo antes de Fee') return isEvenPoint ? 'top' : 'right';
                        if (context.dataset.label === 'Valor Comprometido') return isEvenPoint ? 'right' : 'left';
                        return isEvenPoint ? 'bottom' : 'left';
                    },
                    anchor: 'end',
                    offset: function(context) {
                        return context.dataIndex % 2 === 0 ? 8 : 16;
                    },
                    clamp: true,
                    color: function(context) {
                        return context.dataset.borderColor || '#20242b';
                    },
                    backgroundColor: 'rgba(255, 255, 255, 0.88)',
                    borderColor: 'rgba(32, 36, 43, 0.15)',
                    borderWidth: 1,
                    borderRadius: 4,
                    padding: 3,
                    font: {
                        size: 9,
                        weight: 'bold'
                    },
                    formatter: function(value) {
                        return formatCurrencyShort(value);
                    }
                },
                legend: { display: false },
                todayLine: {
                    dateLabelsRaw: dateLabelsRaw,
                    todayStr: todayStr,
                    label: 'REVISION',
                    color: '#813f32',
                    showLabel: false
                },
                tooltip: {
                    callbacks: {
                        title: tooltipFullDateTitle,
                        labelColor: function(context) {
                            var color = context.dataset.borderColor || '#6c757d';
                            return {
                                borderColor: color,
                                backgroundColor: color
                            };
                        },
                        label: function(context) {
                            let label = context.dataset.label || '';
                            if (label) {
                                label += ': ';
                            }
                            if (context.parsed.y !== null) {
                                label += new Intl.NumberFormat('es-MX', {
                                    style: 'currency',
                                    currency: 'MXN'
                                }).format(context.parsed.y);
                            }
                            return label;
                        }
                    }
                }
            }
        }
    });
    generateLineLegend(chartCosts, 'legendAccumulatedCosts');
});

                document.addEventListener("DOMContentLoaded", function() {
                    var tasks = ;
                    var ganttInitialized = false;
                    var gantt;

                    function syncSidebar() {
                        var sidebarRowsContainer = document.getElementById("gantt-sidebar-rows");
                        if (!sidebarRowsContainer) return;
                        sidebarRowsContainer.innerHTML = "";

                        var gridRows = document.querySelectorAll('#gantt-chart-svg .grid-row');
                        if (gridRows.length === 0) return;

                        gridRows.forEach(function(gridRow, index) {
                            var y = parseFloat(gridRow.getAttribute('y'));
                            var height = parseFloat(gridRow.getAttribute('height'));
                            if (isNaN(y) || isNaN(height)) return;
                            var task = tasks[index];
                            if (task) {
                                var rowEl = document.createElement("div");
                                rowEl.className = "gantt-sidebar-row d-flex align-items-center";
                                rowEl.style.position = "absolute";
                                rowEl.style.top = y + "px";
                                rowEl.style.height = height + "px";
                                rowEl.style.left = "0";
                                rowEl.style.right = "0";
                                rowEl.style.padding = "0 15px";
                                rowEl.style.borderBottom = "1px solid #ebe8e5";
                                rowEl.style.fontSize = "11.5px";
                                rowEl.style.fontWeight = "700";
                                rowEl.style.color = "#20242b";
                                rowEl.style.cursor = "pointer";
                                rowEl.style.transition = "background-color 0.2s ease";

                                var seq = (index + 1) < 10 ? '0' + (index + 1) : (index + 1);
                                rowEl.innerHTML = '' + seq + '' +
                                                  '' + task.name + '';

                                rowEl.addEventListener("click", function() {
                                    if (task.url) {
                                        window.location.href = task.url;
                                    }
                                });

                                sidebarRowsContainer.appendChild(rowEl);
                            }
                        });

                        var svgEl = document.getElementById("gantt-chart-svg");
                        var sidebarEl = document.getElementById("gantt-tasks-sidebar");
                        if (svgEl && sidebarEl) {
                            var svgHeight = svgEl.getAttribute('height') || svgEl.getBoundingClientRect().height;
                            if (svgHeight) {
                                sidebarEl.style.height = svgHeight + "px";
                            }
                        }
                    }

                    function initGantt() {
                        if (ganttInitialized) return;
                        var svgEl = document.getElementById("gantt-chart-svg");
                        if (!svgEl) return;
                        if (!tasks || tasks.length === 0) {
                            document.getElementById("gantt-chart-svg").innerHTML = '<text x="50%" y="50%" text-anchor="middle" dominant-baseline="middle" fill="#6c757d">No hay tareas planificadas en este rango.</text>';
                            return;
                        }

                        gantt = new Gantt("#gantt-chart-svg", tasks, {
                            view_mode: 'Week',
                            language: 'es',
                            custom_popup_html: function(task) {
                                var t = tasks.find(function(item) { return item.id === task.id; }) || task;

                                var statusBadgeClass = 'bg-secondary';
                                if (t.state_key === 'programadas') statusBadgeClass = 'bg-primary';
                                else if (t.state_key === 'ejecucion') statusBadgeClass = 'bg-warning text-dark';
                                else if (t.state_key === 'validacion') statusBadgeClass = 'bg-info text-white';
                                else if (t.state_key === 'cerradas') statusBadgeClass = 'bg-success';

                                var supInt = t.supervisor_interno ? t.supervisor_interno : '-';
                                var supCli = t.supervisor_cliente ? t.supervisor_cliente : '-';

                                var html = '
';
                                html += '
';
                                html += '
' + t.name + '';
                                html += '' + t.status_label + '';
                                html += '';
                                html += '
';
                                html += ' ' + t.start + ' a ' + t.end;
                                html += '';
                                html += '
';
                                html += '
';
                                html += 'Avance Físico';
                                html += '' + t.progress + '%';
                                html += '';
                                html += '
';
                                html += '
';
                                html += '';
                                html += '';
                                html += '
';
                                html += '
';
                                html += 'Sup. Interno:';
                                html += '' + supInt + '';
                                html += '';
                                html += '
';
                                html += 'Sup. Cliente:';
                                html += '' + supCli + '';
                                html += '';
                                html += '';
                                html += '
';
                                html += ' Doble clic para ver detalles';
                                html += '';
                                html += '';
                                return html;
                            },
                            on_click: function (task) {
                                // Double click handles redirect, single click shows tooltip
                            },
                            on_date_change: function(task, start, end) {
                                // Read-only
                            },
                            on_progress_change: function(task, progress) {
                                // Read-only
                            }
                        });

                        // Double click to redirect
                        document.querySelectorAll('#gantt-chart-svg .bar-wrapper').forEach(function(bar) {
                            bar.addEventListener('dblclick', function() {
                                var taskId = bar.getAttribute('data-id');
                                var taskObj = tasks.find(function(t) { return t.id === taskId; });
                                if (taskObj && taskObj.url) {
                                    window.location.href = taskObj.url;
                                }
                            });
                        });

                        // Compute average progress and update KPI strip
                        if (tasks && tasks.length > 0) {
                            var totalProgress = 0;
                            tasks.forEach(function(t) {
                                totalProgress += t.progress || 0;
                            });
                            var avgProgress = Math.round(totalProgress / tasks.length);
                            var kpiProgressEl = document.getElementById("gantt-kpi-progress");
                            if (kpiProgressEl) {
                                kpiProgressEl.innerText = avgProgress + "%";
                            }
                        }

                        ganttInitialized = true;

                        // Sync sidebar vertical coordinates after render
                        setTimeout(syncSidebar, 50);
                    }

                    // Initialize Gantt when its tab becomes visible
                    var ganttTab = document.getElementById('gantt-view-tab');
                    if (ganttTab) {
                        ganttTab.addEventListener('shown.bs.tab', function() {
                            initGantt();
                        });
                    }
                    if (document.getElementById('ganttViewPane') && document.getElementById('ganttViewPane').classList.contains('active')) {
                        initGantt();
                    }

                    // Zoom/Scale buttons
                    document.querySelectorAll('.gantt-scale-btn').forEach(function(btn) {
                        btn.addEventListener('click', function() {
                            document.querySelectorAll('.gantt-scale-btn').forEach(function(b) {
                                b.classList.remove('active');
                            });
                            btn.classList.add('active');
                            var scale = btn.getAttribute('data-scale');
                            if (gantt) {
                                gantt.change_view_mode(scale);
                                setTimeout(syncSidebar, 50);
                            }
                        });
                    });
                });

div.script:
document.addEventListener("DOMContentLoaded", function() {
    var dateLabels = ;
    var dateLabelsRaw = ;
    var todayStr = ;

    function parseLocalDate(dateStr) {
        var parts = (dateStr || '').split('-').map(Number);
        if (parts.length !== 3) return null;
        return new Date(parts[0], parts[1] - 1, parts[2]).getTime();
    }

    function formatFullDateLabel(rawDate) {
        var parts = (rawDate || '').split('-').map(Number);
        if (parts.length !== 3) return rawDate || '';
        return new Intl.DateTimeFormat('es-MX', {
            day: 'numeric',
            month: 'long',
            year: 'numeric'
        }).format(new Date(parts[0], parts[1] - 1, parts[2]));
    }

    function tooltipFullDateTitle(items) {
        if (!items.length) return '';
        return formatFullDateLabel(dateLabelsRaw[items[0].dataIndex]);
    }

    function tooltipFullDateTitleFrom(rawLabels) {
        return function(items) {
            if (!items.length) return '';
            return formatFullDateLabel(rawLabels[items[0].dataIndex]);
        };
    }

    // Helper to get X position for "Today" line
    function getXForToday(chart, dateLabelsRaw, todayStr) {
        if (!dateLabelsRaw || !todayStr || dateLabelsRaw.length === 0) return null;
        var todayTime = parseLocalDate(todayStr);
        var points = dateLabelsRaw.map(function(value, index) {
            return {
                index: index,
                time: parseLocalDate(value)
            };
        }).filter(function(point) {
            return point.time !== null;
        });
        if (!points.length || todayTime === null) return null;

        var minTime = points[0].time;
        var maxTime = points[points.length - 1].time;

        if (minTime > todayTime) return null;
        if (todayTime > maxTime) return null;

        function getXForIndex(index) {
            if (chart.scales.x.getPixelForValue) {
                return chart.scales.x.getPixelForValue(index);
            }
            return chart.scales.x.getPixelForTick(index);
        }

        if (points.length === 1) {
            if (points[0].time === todayTime) {
                return getXForIndex(points[0].index);
            }
        }

        for (var i = 0; points.length - 1 > i; i++) {
            if (todayTime >= points[i].time) {
                if (points[i+1].time >= todayTime) {
                    var t0 = points[i].time;
                    var t1 = points[i+1].time;
                    var ratio = t1 === t0 ? 0 : (todayTime - t0) / (t1 - t0);

                    var x0 = getXForIndex(points[i].index);
                    var x1 = getXForIndex(points[i+1].index);

                    return x0 + ratio * (x1 - x0);
                }
            }
        }
        return null;
    }

    function getTodayIndex(dateLabelsRaw, todayStr) {
        var todayTime = parseLocalDate(todayStr);
        if (!dateLabelsRaw || todayTime === null) return -1;
        for (var i = 0; dateLabelsRaw.length > i; i++) {
            if (parseLocalDate(dateLabelsRaw[i]) === todayTime) {
                return i;
            }
        }
        return -1;
    }

    var todayIndex = getTodayIndex(dateLabelsRaw, todayStr);

    function pointRadiusForCut(context) {
        return context.dataIndex === todayIndex ? 5 : 2;
    }

    function pointHoverRadiusForCut(context) {
        return context.dataIndex === todayIndex ? 7 : 5;
    }

    function formatCurrencyShort(value) {
        return new Intl.NumberFormat('es-MX', {
            style: 'currency',
            currency: 'MXN',
            notation: 'compact',
            maximumFractionDigits: 1
        }).format(value);
    }

    function hideChartLoader(chart) {
        var canvas = chart.canvas;
        var frame = canvas ? canvas.closest('.portal-project-chart-frame') : null;
        var loader = frame ? frame.querySelector('.portal-project-chart-loader') : null;
        if (frame) {
            frame.classList.add('is-loaded');
        }
        if (loader) {
            loader.classList.add('is-loaded');
        }
    }

    const chartLoaderPlugin = {
        id: 'chartLoader',
        afterRender: hideChartLoader,
        afterDraw: hideChartLoader
    };

    // Today vertical cut line plugin
    const todayLinePlugin = {
        id: 'todayLine',
        afterDatasetsDraw: function(chart, args, options) {
            try {
                options = options || {};
                var dateLabelsRaw = options.dateLabelsRaw;
                var todayStr = options.todayStr;
                if (!chart.chartArea || !chart.scales || !chart.scales.x) return;
                var xPos = getXForToday(chart, dateLabelsRaw, todayStr);
                if (xPos !== null) {
                    var ctx = chart.ctx;
                    var area = chart.chartArea;
                    var label = options.label || 'HOY';
                    var lineColor = options.color || '#111827';
                    var showLabel = options.showLabel !== false;
                    ctx.save();
                    ctx.beginPath();
                    ctx.strokeStyle = lineColor;
                    ctx.lineWidth = 2;
                    ctx.setLineDash([5, 4]);
                    ctx.moveTo(xPos, area.top);
                    ctx.lineTo(xPos, area.bottom);
                    ctx.stroke();

                    if (!showLabel) {
                        ctx.restore();
                        return;
                    }

                    ctx.setLineDash([]);
                    ctx.font = 'bold 10px sans-serif';
                    ctx.textAlign = 'center';
                    ctx.textBaseline = 'middle';
                    var metrics = ctx.measureText(label);
                    var paddingX = 5;
                    var labelWidth = metrics.width + paddingX * 2;
                    var labelHeight = 18;
                    var labelX = Math.min(Math.max(xPos, area.left + labelWidth / 2), area.right - labelWidth / 2);
                    var labelY = area.top + 10;
                    ctx.fillStyle = '#ffffff';
                    ctx.strokeStyle = lineColor;
                    ctx.lineWidth = 1;
                    ctx.beginPath();
                    if (ctx.roundRect) {
                        ctx.roundRect(labelX - labelWidth / 2, labelY - labelHeight / 2, labelWidth, labelHeight, 4);
                    } else {
                        ctx.rect(labelX - labelWidth / 2, labelY - labelHeight / 2, labelWidth, labelHeight);
                    }
                    ctx.fill();
                    ctx.stroke();
                    ctx.fillStyle = lineColor;
                    ctx.fillText(label, labelX, labelY + 1);
                    ctx.restore();
                }
            } catch (error) {
                console.warn('No se pudo dibujar la linea de HOY en el grafico.', error);
            }
        }
    };

    var avanceReal = ;
    var avancePlaneado = ;

    var hhDateLabels = ;
    var hhDateLabelsRaw = ;
    var hhPlaneadas = ;
    var hhReales = ;

    var costoReal = ;
    var costoPlaneado = ;
    var costoComprometido = ;
    var costoExpuesto = ;

    // Helper function for line-and-dot custom legend
    function generateLineLegend(chart, legendContainerId) {
         const legendContainer = document.getElementById(legendContainerId);
         if (legendContainer) {
             legendContainer.innerHTML = '';
             chart.data.datasets.forEach((dataset, i) => {
                 const label = dataset.label;
                 const color = dataset.borderColor || dataset.backgroundColor;
                 const isBarLegend = legendContainerId === 'legendSingleTaskManHours';
                 const markerHtml = isBarLegend
                     ? ``
                     : `


                     `;

                 const legendItem = document.createElement('div');
                 legendItem.className = 'legend-item d-flex align-items-center';
                 legendItem.style.cursor = 'pointer';
                 legendItem.style.fontSize = '0.85rem';
                 legendItem.style.userSelect = 'none';
                 legendItem.style.transition = 'opacity 0.2s';

                 legendItem.innerHTML = `
                     ${markerHtml}
                     ${label}
                 `;

                 legendItem.addEventListener('click', () => {
                     const isVisible = chart.isDatasetVisible(i);
                     if (isVisible) {
                         chart.hide(i);
                         legendItem.style.opacity = '0.3';
                         legendItem.style.textDecoration = 'line-through';
                     } else {
                         chart.show(i);
                         legendItem.style.opacity = '1';
                         legendItem.style.textDecoration = 'none';
                     }
                 });

                 legendContainer.appendChild(legendItem);
             });
         }
     }

    // Chart 1: Evolución de Avance General
    const chartAdvance = new Chart(document.getElementById('chartSingleTaskGeneralAdvance'), {
        type: 'line',
        plugins: [ChartDataLabels, todayLinePlugin, chartLoaderPlugin],
        data: {
            labels: dateLabels,
            datasets: [
                {
                    label: 'Avance Real',
                    data: avanceReal,
                    borderColor: '#1b8b50',
                    backgroundColor: '#1b8b50',
                    tension: 0.2,
                    fill: false,
                    pointStyle: 'circle',
                    pointRadius: pointRadiusForCut,
                    pointHoverRadius: pointHoverRadiusForCut,
                    pointBorderColor: '#ffffff',
                    pointBorderWidth: 2
                },
                {
                    label: 'Avance Planeado',
                    data: avancePlaneado,
                    borderColor: '#ef8318',
                    backgroundColor: '#ef8318',
                    tension: 0.2,
                    fill: false,
                    pointStyle: 'circle',
                    pointRadius: pointRadiusForCut,
                    pointHoverRadius: pointHoverRadiusForCut,
                    pointBorderColor: '#ffffff',
                    pointBorderWidth: 2
                }
            ]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            layout: {
                padding: {
                    top: 12,
                    bottom: 12
                }
            },
            plugins: {
                datalabels: {
                    display: false,
                    align: function(context) {
                        if (context.datasetIndex === 0) {
                            return context.dataIndex % 2 === 0 ? 'top' : 'right';
                        }
                        return context.dataIndex % 2 === 0 ? 'bottom' : 'left';
                    },
                    anchor: 'end',
                    offset: function(context) {
                        return context.dataIndex % 2 === 0 ? 8 : 16;
                    },
                    clamp: true,
                    color: '#20242b',
                    backgroundColor: 'rgba(255, 255, 255, 0.88)',
                    borderColor: 'rgba(32, 36, 43, 0.15)',
                    borderWidth: 1,
                    borderRadius: 4,
                    padding: 3,
                    font: {
                        size: 9,
                        weight: 'bold'
                    },
                    formatter: function(value) {
                        return value.toFixed(1) + '%';
                    }
                },
                legend: { display: false },
                todayLine: {
                    dateLabelsRaw: dateLabelsRaw,
                    todayStr: todayStr,
                    label: 'REVISION',
                    color: '#813f32',
                    showLabel: false
                },
                tooltip: {
                    callbacks: {
                        title: tooltipFullDateTitle,
                        label: function(context) {
                            var label = context.dataset.label || '';
                            var value = context.parsed.y || 0;
                            return label + ': ' + value.toFixed(1) + '%';
                        },
                        footer: function(items) {
                            if (!items.length) return '';
                            var i = items[0].dataIndex;
                            var real = avanceReal[i] || 0;
                            var plan = avancePlaneado[i] || 0;
                            var gap = real - plan;
                            var sign = gap > 0 ? '+' : '';
                            return 'Desviacion vs plan: ' + sign + gap.toFixed(1) + '%';
                        }
                    }
                }
            },
            scales: {
                y: {
                    min: 0,
                    max: 100,
                    ticks: {
                        stepSize: 25,
                        callback: function(value) {
                            return value + '%';
                        }
                    }
                }
            }
        }
    });
    generateLineLegend(chartAdvance, 'legendSingleTaskGeneralAdvance');

    // Chart 2: HH Reales vs Planeadas
    const chartManHours = new Chart(document.getElementById('chartSingleTaskManHours'), {
        type: 'bar',
        plugins: [ChartDataLabels, chartLoaderPlugin],
        data: {
            labels: hhDateLabels,
            datasets: [
                {
                    label: 'HH Planeadas',
                    data: hhPlaneadas,
                    backgroundColor: '#007bff',
                    borderRadius: 4
                },
                {
                    label: 'HH Reales',
                    data: hhReales,
                    backgroundColor: '#28a745',
                    borderRadius: 4
                }
            ]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
                legend: { display: false },
                datalabels: {
                    anchor: 'end',
                    align: 'top',
                    color: '#495057',
                    font: {
                        weight: 'bold',
                        size: 11
                    },
                    formatter: function(value) {
                        return value !== 0 ? value : '';
                    }
                },
                tooltip: {
                    callbacks: {
                        title: tooltipFullDateTitleFrom(hhDateLabelsRaw)
                    }
                }
            },
            scales: { y: { beginAtZero: true, grace: '20%' } }
        }
    });
    generateLineLegend(chartManHours, 'legendSingleTaskManHours');

    // Chart 3: Costo antes de Fee, comprometido vs planeado (Acumulado)
    const chartCosts = new Chart(document.getElementById('chartSingleTaskAccumulatedCosts'), {
        type: 'line',
        plugins: [ChartDataLabels, todayLinePlugin, chartLoaderPlugin],
        data: {
            labels: dateLabels,
            datasets: [
                {
                    label: 'Costo antes de Fee',
                    data: costoReal,
                    borderColor: '#28a745',
                    backgroundColor: 'rgba(40, 167, 69, 0.1)',
                    fill: true,
                    tension: 0.2,
                    pointStyle: 'circle',
                    pointRadius: pointRadiusForCut,
                    pointHoverRadius: pointHoverRadiusForCut,
                    pointBorderColor: '#ffffff',
                    pointBorderWidth: 2
                },
                {
                    label: 'Valor Comprometido',
                    data: costoComprometido,
                    borderColor: '#6f42c1',
                    backgroundColor: 'rgba(111, 66, 193, 0.08)',
                    fill: false,
                    tension: 0.2,
                    pointStyle: 'circle',
                    pointRadius: pointRadiusForCut,
                    pointHoverRadius: pointHoverRadiusForCut,
                    pointBorderColor: '#ffffff',
                    pointBorderWidth: 2
                },
                {
                    label: 'Valor Planeado',
                    data: costoPlaneado,
                    borderColor: '#fd7e14',
                    backgroundColor: 'rgba(253, 126, 20, 0.1)',
                    fill: true,
                    tension: 0.2,
                    pointStyle: 'circle',
                    pointRadius: pointRadiusForCut,
                    pointHoverRadius: pointHoverRadiusForCut,
                    pointBorderColor: '#ffffff',
                    pointBorderWidth: 2
                }
            ]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            layout: {
                padding: {
                    top: 12,
                    bottom: 12
                }
            },
            scales: {
                y: {
                    beginAtZero: true,
                    grace: '18%',
                    ticks: {
                        callback: function(value) {
                            return new Intl.NumberFormat('es-MX', {
                                style: 'currency',
                                currency: 'MXN',
                                maximumFractionDigits: 0
                            }).format(value);
                        }
                    }
                }
            },
            plugins: {
                datalabels: {
                    display: false,
                    align: function(context) {
                        var isEvenPoint = context.dataIndex % 2 === 0;
                        if (context.dataset.label === 'Costo antes de Fee') return isEvenPoint ? 'top' : 'right';
                        if (context.dataset.label === 'Valor Comprometido') return isEvenPoint ? 'right' : 'left';
                        return isEvenPoint ? 'bottom' : 'left';
                    },
                    anchor: 'end',
                    offset: function(context) {
                        return context.dataIndex % 2 === 0 ? 8 : 16;
                    },
                    clamp: true,
                    color: function(context) {
                        return context.dataset.borderColor || '#20242b';
                    },
                    backgroundColor: 'rgba(255, 255, 255, 0.88)',
                    borderColor: 'rgba(32, 36, 43, 0.15)',
                    borderWidth: 1,
                    borderRadius: 4,
                    padding: 3,
                    font: {
                        size: 9,
                        weight: 'bold'
                    },
                    formatter: function(value) {
                        return formatCurrencyShort(value);
                    }
                },
                legend: { display: false },
                todayLine: {
                    dateLabelsRaw: dateLabelsRaw,
                    todayStr: todayStr,
                    label: 'REVISION',
                    color: '#813f32',
                    showLabel: false
                },
                tooltip: {
                    callbacks: {
                        title: tooltipFullDateTitle,
                        labelColor: function(context) {
                            var color = context.dataset.borderColor || '#6c757d';
                            return {
                                borderColor: color,
                                backgroundColor: color
                            };
                        },
                        label: function(context) {
                            let label = context.dataset.label || '';
                            if (label) {
                                label += ': ';
                            }
                            if (context.parsed.y !== null) {
                                label += new Intl.NumberFormat('es-MX', {
                                    style: 'currency',
                                    currency: 'MXN'
                                }).format(context.parsed.y);
                            }
                            return label;
                        }
                    }
                }
            }
        }
    });
    generateLineLegend(chartCosts, 'legendSingleTaskAccumulatedCosts');
});

template.script:
document.addEventListener("DOMContentLoaded", function() {
    if (!window.bootstrap || !window.bootstrap.Tooltip) return;
    document.querySelectorAll('.portal-project-kpi-help[data-bs-toggle="tooltip"]').forEach(function(element) {
        if (element.dataset.portalKpiTooltipReady) return;
        element.dataset.portalKpiTooltipReady = '1';
        new window.bootstrap.Tooltip(element);
    });
});

document.addEventListener("DOMContentLoaded", function() {
    function getFieldLabel(field) {
        var label = field.id ? document.querySelector('label[for="' + field.id + '"]') : null;
        return label ? label.textContent.trim() : field.name;
    }

    function getFieldValueText(field) {
        if (field.tagName === 'SELECT') {
            var option = field.options[field.selectedIndex];
            return option ? option.textContent.trim() : '';
        }
        return field.value || '';
    }

    function isActiveFilterField(field) {
        if (!field.name || field.disabled) return false;
        if (['view', 'page_size', 'sortby', 'sort_order', 'search_in'].indexOf(field.name) !== -1) {
            return false;
        }
        if (!field.value) return false;
        if (field.name === 'groupby' && field.value === 'none') return false;
        return true;
    }

    function buildFilterSummary(form) {
        var active = [];
        form.querySelectorAll('input[name], select[name]').forEach(function(field) {
            if (!isActiveFilterField(field)) return;
            var valueText = getFieldValueText(field);
            if (!valueText || valueText === 'Todos' || valueText === 'Todas') return;
            active.push(getFieldLabel(field) + ': ' + valueText);
        });
        return active;
    }

    function getCurrentTaskView(form) {
        var activeTab = document.querySelector('#taskViewTabs .nav-link.active');
        if (activeTab) {
            if (activeTab.id === 'list-view-tab') return 'list';
            if (activeTab.id === 'kanban-view-tab') return 'kanban';
            if (activeTab.id === 'gantt-view-tab') return 'gantt';
        }

        var currentView = new URLSearchParams(window.location.search).get('view');
        if (['list', 'kanban', 'gantt'].indexOf(currentView) !== -1) {
            return currentView;
        }

        var viewInput = form.querySelector('input[name="view"]');
        return viewInput ? viewInput.value : '';
    }

    function syncTaskView(form) {
        if (!form || form.getAttribute('action') !== '/my/control-obra/tareas') return;
        var viewInput = form.querySelector('input[name="view"]');
        if (!viewInput) return;
        var currentView = getCurrentTaskView(form);
        if (['list', 'kanban', 'gantt'].indexOf(currentView) !== -1) {
            viewInput.value = currentView;
        }
    }

    function ensureSummary(button, form, activeFilters) {
        var wrapper = button.closest('.d-flex');
        var summary = wrapper ? wrapper.nextElementSibling : null;
        if (!summary || !summary.classList.contains('portal-project-filter-summary')) {
            summary = document.createElement('div');
            summary.className = 'portal-project-filter-summary d-none';
            if (wrapper) {
                wrapper.parentNode.insertBefore(summary, wrapper.nextSibling);
            }
        }

        if (!activeFilters.length) {
            summary.classList.add('d-none');
            summary.innerHTML = '';
            return;
        }

        summary.classList.remove('d-none');
        summary.replaceChildren();

        var icon = document.createElement('i');
        icon.className = 'fa fa-info-circle';
        summary.appendChild(icon);

        var text = document.createElement('span');
        text.appendChild(document.createTextNode('Vista filtrada por '));
        activeFilters.forEach(function(item, index) {
            if (index) {
                var separator = document.createElement('span');
                separator.className = 'portal-project-filter-summary-separator';
                separator.textContent = '/';
                text.appendChild(separator);
            }
            var strong = document.createElement('strong');
            strong.textContent = item;
            text.appendChild(strong);
        });
        summary.appendChild(text);
    }

    function setFilterState(button, form, expanded, activeFilters) {
        form.classList.toggle('d-none', !expanded);
        button.classList.toggle('btn-outline-secondary', !expanded || !activeFilters.length);
        button.classList.toggle('btn-secondary', expanded && !activeFilters.length);
        button.classList.toggle('btn-info', activeFilters.length > 0);

        var label = button.querySelector('span');
        if (label) {
            if (expanded) {
                label.textContent = 'Ocultar filtros';
            } else {
                label.textContent = activeFilters.length ? 'Filtros activos' : 'Mostrar filtros';
            }
        }
    }

    document.querySelectorAll('.portal-project-filter-toggle').forEach(function(button) {
        if (button.dataset.portalFilterReady) return;
        button.dataset.portalFilterReady = '1';

        var form = button.parentElement ? button.parentElement.nextElementSibling : null;
        if (!form || !form.classList.contains('portal-project-filter-form')) return;
        syncTaskView(form);
        form.addEventListener('change', function() {
            syncTaskView(form);
        }, true);
        form.addEventListener('submit', function() {
            syncTaskView(form);
        });
        var activeFilters = buildFilterSummary(form);
        ensureSummary(button, form, activeFilters);
        setFilterState(button, form, activeFilters.length > 0, activeFilters);

        button.addEventListener('click', function() {
            var isHidden = form.classList.contains('d-none');
            activeFilters = buildFilterSummary(form);
            ensureSummary(button, form, activeFilters);
            setFilterState(button, form, isHidden, activeFilters);
        });
    });
});
